(4881, 54, 35, 530, 27, 212, 'نِّعْمَةً مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ'),
(4882, 54, 36, 530, 27, 212, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ'),
(4883, 54, 37, 530, 27, 212, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ'),
(4884, 54, 38, 530, 27, 212, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ'),
(4885, 54, 39, 530, 27, 212, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ'),
(4886, 54, 40, 530, 27, 212, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ'),
(4887, 54, 41, 530, 27, 212, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ'),
